# -*- coding: utf-8 -*-
# ---------- 4. Los coliridianos: Epifanio y los demás ----------
HOLL = "Epifanio de Salamina, Panarion, ed. K. Holl, GCS 37 (Leipzig 1933)"
HOLLU = "https://archive.org/details/epiphanius-panarion-and-ancoratus-greek-critical-edition-3-vols-in-1-holl-1915-1922-1933"
ARC = "archive.org (texto OCR de la edición impresa; se conservan las erratas del OCR)"
WIL = "Traducción española propia a partir de la inglesa de F. Williams (The Panarion, Brill 2013), cotejada con el griego; entre corchetes, aclaraciones. "
GR = "griego (OCR de la edición crítica de Holl)"

add(4, "Epifanio de Salamina (m. 403)", key="Ep1", specs=["T3-02", "T3-01"], lang=GR, trnote=WIL,
 title="Epifanio: «coliridianos, que ofrecen una torta en nombre de María… les pusimos nosotros el nombre»; y «se cuenta» que unas mujeres de Tracia lo llevaron a Arabia",
 ref=f"{HOLL}, p. 415 (resumen del libro VII, n.º 79) y p. 473 (Panarion 78.23.3–4)",
 ar_ref="Panarion, Anaceph. VII 79; 78.23.3–4", site=ARC, url=HOLLU,
 es=["79. Coliridianos: los que, en nombre de esta misma María, [[k:en un día fijado del año ofrecen una torta (kollyrís); a ellos les pusimos]] [[k:un nombre de acuerdo con su práctica]], llamándolos coliridianos.",
     "Y igual que digo que me ha asombrado oír que algunos se han atrevido a entregarse al pecado con toda facilidad, también me asombra oír lo otro: he oído que otros, que han perdido el juicio sobre esta santa siempre Virgen, se han esforzado y se esfuerzan [[k:por introducirla a ella en lugar de Dios]], llevados por una especie de locura y desvarío. [[k:Pues se cuenta]] [[k:que unas mujeres, allí en Arabia, venidas de las tierras de Tracia]], han introducido esta tontería: [[k:hacen una torta (kollyrís) en nombre de la siempre Virgen y se reúnen para ello]], e intentan en nombre de la santa Virgen algo desmedido y emprenden un acto ilícito y blasfemo, [[k:y ofician en su nombre por medio de mujeres]]. Todo esto es impío e ilícito, ajeno a la predicación del Espíritu Santo; es obra del diablo y doctrina de un espíritu impuro."],
 prueba="Es la única fuente original sobre los coliridianos. Epifanio, obispo de Chipre, escribe hacia el año 375 que unas mujeres en Arabia ofrecen una torta en nombre de María e intentan ponerla «en lugar de Dios». Es el texto en que se apoyan los que defienden 5:116.",
 ojo="Fíjate en tres cosas. El nombre «coliridianos» lo inventó él: «les pusimos un nombre de acuerdo con su práctica». Él no los vio: «se cuenta», «he oído». Y la «Arabia» de Epifanio es la provincia romana de Arabia (la actual Jordania y el sur de Siria), no La Meca ni Medina, y dos siglos y medio antes del islam.")

add(4, "Epifanio de Salamina (m. 403)", key="Ep2", specs=["T3-03", "T3-04"], lang=GR, trnote=WIL,
 title="Panarion 79: «una herejía ha salido a la luz… llevada a Arabia desde Tracia y la alta Escitia»: «unas mujeres… ponen un pan y lo ofrecen en nombre de María, y todas comen del pan»",
 ref=f"{HOLL}, pp. 475–476 (Panarion 79.1.1–7)",
 ar_ref="Panarion 79.1.1–7", site=ARC, url=HOLLU,
 es=["Después de esta, otra herejía ha salido a la luz, [[k:de la que ya dije algo en la anterior]], [[k:en la carta sobre María que escribí a Arabia]]. Y también esta herejía, otra vez, [[k:apareció en Arabia, desde Tracia y las partes altas de Escitia]]…",
     "[[k:…y ha llegado a nuestros oídos]]; también ella es ridícula y, a juicio de los sensatos, llena de burla. Empecemos, pues, a hablar de ella y a contar lo suyo: se la juzgará más necia que sensata, como otras parecidas. Porque, igual que hace tiempo los que, por desprecio a María, se dieron a sospechar esas cosas sembraban sospechas dañinas en las mentes de la gente, así también estos, inclinándose al otro extremo, caen en el colmo del daño […]. El daño de ambas herejías es igual: unos rebajan a la santa Virgen, [[k:y los otros, en cambio, la glorifican más de lo debido]]. Pues los que enseñan esto, [[k:¿quiénes son sino mujeres?]] Las mujeres son un género inestable, propenso al error y de pensamiento mezquino. […] Pues unas mujeres adornan un sillón de barbero o un asiento cuadrado, extienden sobre él un paño, y en un día señalado del año [[k:ponen un pan y lo ofrecen en nombre de María, y todas]] [[k:comen del pan]], como ya expliqué en parte en la misma carta a Arabia."],
 prueba="Es la descripción completa del rito: unas mujeres ponen un pan sobre un asiento cubierto con un paño, lo ofrecen «en nombre de María» una vez al año y todas comen de él. Epifanio lo considera una herejía que «glorifica a la Virgen más de lo debido».",
 ojo="El rito parece una ofrenda o comida sagrada en honor de María, no un culto con María como tercera persona de una trinidad. Epifanio vuelve a reconocer que lo sabe de oídas («ha llegado a nuestros oídos»). Y parte de su crítica es que las que ofician son mujeres: «¿quiénes son sino mujeres?».")

add(4, "Epifanio de Salamina (m. 403)", key="Ep3", specs=["T3-05", "T3-06"], lang=GR, trnote=WIL,
 title="Epifanio: «el cuerpo de María era santo, pero no Dios»… «Honrad a María; adorad al Padre, al Hijo y al Espíritu Santo; que nadie adore a María»",
 ref=f"{HOLL}, p. 479 (Panarion 79.4.4–6) y p. 482 (79.7.5–7)",
 ar_ref="Panarion 79.4.4–6; 79.7.5–7", site=ARC, url=HOLLU,
 es=["Pues ¿cómo no le parecerá una locura semejante cosa a todo el que tenga sensatez en Dios? [[k:¿Cómo no ha de ser idolátrica esta práctica, y diabólica esta empresa?]] Porque el diablo, colándose siempre en la mente de los hombres con apariencia de justicia, [[k:divinizando la naturaleza mortal]] ante los ojos de los hombres, trazó con toda clase de artes imágenes de forma humana. […] Sí, ciertamente era santo el cuerpo [[k:de María, pero no Dios]]; sí, era virgen la Virgen, y honrada, [[k:pero no se nos dio para adorarla]], sino que ella adora al que nació de su carne y vino del cielo, del seno del Padre.",
     "[[k:Que María sea honrada]], y que el Padre, el Hijo y el Espíritu Santo sean adorados: [[k:que nadie adore a María]]. No digo a una mujer: ni siquiera a un hombre se le ha mandado [[k:ofrecer el misterio [la eucaristía] como a Dios]]; [[k:ni los ángeles admiten semejante glorificación]]. Que se borre lo mal escrito en el corazón de los engañados […]; que Eva, con Adán, se avergüence y honre solo a Dios […]. Que nadie coma del error que ha surgido a propósito de santa María; pues aunque el árbol sea hermoso, no es para comer, y aunque María sea bellísima, santa y honrada, no es para ser adorada."],
 prueba="Es la mejor prueba de que la Iglesia rechazaba adorar a María. El mismo obispo que cuenta lo de los coliridianos lo condena: «Que María sea honrada, que el Padre, el Hijo y el Espíritu Santo sean adorados: que nadie adore a María». La Trinidad de Epifanio es Padre, Hijo y Espíritu Santo.",
 ojo="Ninguno contra el punto. Al contrario: si el Corán describiera a los coliridianos, estaría describiendo una herejía que la propia Iglesia condenaba, no la fe cristiana.")

add(4, "Epifanio de Salamina (m. 403)", key="Ep4", specs=["T3-07", "T3-08"], lang=GR, trnote=WIL,
 title="Epifanio lo compara con Jeremías 7:18: las tortas «para el ejército del cielo»… «que no digan: honramos a la reina del cielo»",
 ref=f"{HOLL}, pp. 482–483 (Panarion 79.8.1–2)",
 ar_ref="Panarion 79.8.1–2", site=ARC, url=HOLLU,
 es=["[[k:Y estas mujeres, a su vez, renuevan la copa para la Fortuna]] y preparan la mesa para el demonio, y no para Dios, como está escrito [Is 65:11], [[k:y se alimentan con alimentos de impiedad]], como dice la palabra divina: «y las mujeres muelen la harina, y los hijos recogen leña [[k:para hacer tortas al ejército]]…",
     "…del cielo» [Jer 7:18]. [[k:Que Jeremías haga callar a tales mujeres]], y que no alboroten al mundo. Que no digan: [[k:«Honramos a la reina del cielo»]] [Jer 44:18]. [[k:Pues Tafnes sabe cómo castigarlas]], y los lugares de Magdolos saben cómo recibir sus cuerpos para la podredumbre."],
 prueba="Epifanio mismo relaciona el rito con un culto pagano del Antiguo Testamento: las tortas que las mujeres de Judá hacían para «la reina del cielo» (Jeremías 7:18 y 44:17–19). Para él, los coliridianos copian esa idolatría.",
 ojo="La comparación es retórica: Epifanio busca un precedente bíblico para condenarlas, no prueba que creyeran que María era una diosa. Por eso la ve como una herejía extraña, no como algo que hicieran los cristianos en general.")

add(4, "Epifanio de Salamina (m. 403)", key="Ep5", specs=["T3-09"], lang=GR, trnote=WIL,
 title="Epifanio admite que no sabe qué hacían: «o le ofrecen la torta como adorándola, o pretenden ofrecerla por ella»",
 ref=f"{HOLL}, p. 484 (Panarion 79.9.3–4)",
 ar_ref="Panarion 79.9.3–4", site=ARC, url=HOLLU,
 es=["¿Y cuánto más se puede decir? Porque, [[k:o bien estas mujeres ociosas le ofrecen a María la torta como adorándola]], [[k:o bien pretenden ofrecer por ella]] este fruto podrido que hemos dicho: todo es necio, ajeno [a la fe], insolencia y engaño movidos por los demonios. Y para no alargar el discurso, basta con lo dicho. [[k:Que María sea honrada; que el Señor sea adorado]]."],
 prueba="Es el dato más importante para el debate. Al final, el propio Epifanio reconoce que no sabe si la torta se ofrecía a María «como adorándola» o «por ella», en su honor o por su intención, como se hacía con los santos.",
 ojo="Si la única fuente duda de que adoraran a María, no se puede presentar a los coliridianos como una secta que creía que María era una diosa, y menos como la explicación de 5:116.")

add(4, "Juan Damasceno (m. 749)", key="JD", specs=["T3-10"], lang="griego (OCR de Migne, PG 94)",
 trnote="Traducción literal propia del griego; entre corchetes, aclaraciones. ",
 title="Juan Damasceno, uno de los primeros que escriben contra el islam, copia la frase de Epifanio palabra por palabra, incluido «les pusimos el nombre»",
 ref="Juan Damasceno, De haeresibus 79, en J.-P. Migne, Patrologia Graeca 94, cols. 727–728",
 ar_ref="De haeresibus 79 (PG 94, 727–728)", site=ARC, url="https://archive.org/details/patrologicursus53migngoog",
 es=["79. Coliridianos: los que en nombre de esta misma María, [[k:en un día fijado del año, ofrecen una torta (kollyrís)]]; [[k:a ellos les pusimos el nombre]] de coliridianos."],
 prueba="A veces se presenta a Juan Damasceno (siglo VIII) como un segundo testigo de los coliridianos. No lo es: su capítulo 79 copia literalmente el resumen de Epifanio.",
 ojo="Ni siquiera cambia el «les pusimos el nombre», que solo tiene sentido en boca de Epifanio. No añade ningún dato propio: ni dónde estaban ni si seguían existiendo en su tiempo.")

add(4, "Agustín de Hipona (m. 430) e Isidoro de Sevilla (m. 636)", key="Ag", specs=["T3-11", "T3-12", "T3-13"],
 lang="latín (OCR de Oehler y texto de The Latin Library)", trnote="Traducción literal propia del latín; entre corchetes, aclaraciones. ",
 title="Agustín sigue la lista de Epifanio y salta de los antidicomarianitas a los mesalianos: «no puse algunas que él puso». Isidoro, igual",
 ref="Agustín, De haeresibus 56–57, en F. Oehler, Corpus haereseologicum I, pp. 213–214; Isidoro, Etymologiae VIII.5.46–47",
 ar_ref="Aug., De haer. 56–57; Isid., Etym. VIII.5", site="archive.org (OCR de Oehler) y thelatinlibrary.com", url="https://archive.org/details/corporishaereseo01epipuoft · https://www.thelatinlibrary.com/isidore/8.shtml",
 es=["[[k:Se llamaron antidicomarianitas los herejes]] que contradicen la virginidad de María hasta afirmar que, después de nacer Cristo, se unió a su marido. [[k:Como última pone Epifanio]] la herejía de los mesalianos, nombre que viene de la lengua siria.",
     "Hasta estos, pues, llevó su obra sobre las herejías el obispo de Chipre antes mencionado, tenido entre los griegos por grande y alabado por muchos por la sanidad de su fe católica. Al enumerar a los herejes, [[k:no seguí su manera, sino su orden]]. [[k:Pues puse algunas tomadas de otros que él no puso, y no puse algunas]] que él puso.",
     "[46] [[k:Los antidicomarianitas se llaman así porque contradicen la virginidad de María]], afirmando que, después de nacer Cristo, se unió a su marido. [[k:[47] Los metangismonitas recibieron ese nombre]] porque en griego «angos» significa vaso."],
 prueba="Se dice a menudo que Agustín menciona a los coliridianos («De haeresibus 79»). Es falso. Agustín sigue el orden de Epifanio: su capítulo 56 son los antidicomarianitas (Epifanio 78) y pasa directamente a los mesalianos (Epifanio 80). Se salta el 79, los coliridianos, y lo dice: «no puse algunas que él puso». Isidoro, que copia a Agustín, tampoco los menciona.",
 ojo="Que Agustín no los incluya no prueba que no existieran. Pero sí prueba que no es un segundo testigo. Según la búsqueda, tampoco aparecen en los catálogos latinos de Filastrio, el Praedestinatus ni el Indiculus del Pseudo-Jerónimo.")

add(4, "Wikipedia (inglés), «Collyridianism»", key="Wk", specs=["T3-14", "T3-15"], lang="inglés",
 trnote="Traducción propia del inglés. ",
 title="Wikipedia: «La existencia de los coliridianos es dudosa: solo se mencionan en el Panarion de Epifanio y posiblemente en el Corán»",
 ref="Wikipedia en inglés, artículo «Collyridianism» (entrada y apartado «Existence»)",
 ar_ref="en.wikipedia.org", site="en.wikipedia.org", url="https://en.wikipedia.org/wiki/Collyridianism",
 es=["La existencia de los coliridianos es dudosa: [[k:solo se mencionan en el Panarion de Epifanio y posiblemente en el Corán]]. Según Epifanio, esta secta [[k:se originó en Tracia y Escitia antes de extenderse a Arabia]], aunque también se ha propuesto un origen en Siria o Asia Menor, y supuestamente estaba compuesta solo por mujeres.",
     "Muchos estudiosos consideran dudosa la existencia de esta secta. [[k:El teólogo Karl Gerok discutió con fuerza la existencia de los coliridianos]], y consideró improbable que una secta formada solo por mujeres hubiera durado tanto como dice Epifanio. Del mismo modo, [[k:el problema de que la única fuente sobre la existencia de esta secta sea un tratado heresiológico de Epifanio]] ha llevado a [[k:Samuel Zwemer]] y a Averil Cameron a dudar de que ese movimiento existiera."],
 prueba="El resumen de consulta más usado coincide con lo que muestran las fuentes: la única fuente es Epifanio, y muchos especialistas dudan de que la secta existiera.",
 ojo="Wikipedia no es una fuente académica, y la propia página avisa de que algunas de sus fuentes pueden no ser fiables. Úsala solo como resumen; las pruebas son Epifanio (#Ep1#–#Ep5#) y los estudios de #Kt# y #QS#.")

add(4, "Ally Kateusz (2019)", key="Kt", specs=["P-KT"], lang="inglés (página del libro, acceso abierto)",
 trnote="Traducción propia del inglés. ",
 title="Kateusz: lo que Epifanio criticaba se parece a una liturgia siríaca en la que se ofrecía pan en nombre de María, sin creer que fuera una diosa",
 ref="Ally Kateusz, Mary and Early Christian Women: Hidden Leadership (Palgrave, 2019, acceso abierto), p. 8",
 ar_ref="Kateusz 2019, p. 8", site="archive.org (PDF de acceso abierto, OAPEN)", url="https://archive.org/download/oapen-20.500.12657-22895/1007266.pdf",
 es=["También en el siglo IV, y sugiriendo de nuevo la importancia de María para las mujeres que dirigían comunidades, el obispo Epifanio de Salamina (c. 310–403) se quejaba de que en una amplia franja del cristianismo oriental, desde Escitia (sur de Rusia) hasta Tracia (Bulgaria) y la península arábiga, [[k:mujeres sacerdotes sacrificaban pan en nombre de María sobre la mesa del altar.]] Esta liturgia pudo ser especialmente común en las iglesias de la antigua Siria […]. En cualquier caso, un manual litúrgico escrito en siríaco antiguo e [[k:incluido en el relato de la Dormición sobre la muerte de María]] conserva una liturgia que mandaba igualmente sacrificar pan en nombre de María en los altares de las iglesias. [[k:Tanto Stephen J. Shoemaker como yo hemos]] defendido que, cuando Epifanio se quejaba de mujeres sacerdotes que sacrificaban pan en nombre de María, al parecer se quejaba de [[k:esta liturgia, o de una liturgia parecida.]]"],
 prueba="Los estudios recientes (Kateusz, y Shoemaker en 2008) leen a los «coliridianos» de otra manera: lo que Epifanio criticaba se parece a una liturgia siríaca en honor de María, conservada en un texto de la Dormición. Esa liturgia no considera a María una diosa.",
 ojo="Kateusz escribe «península arábiga», pero Epifanio solo dice «Arabia», que en su tiempo era sobre todo la provincia romana. Y su interés es la historia de las mujeres en la Iglesia, no el Corán. Shoemaker resume así su artículo (JECS 16, 2008, solo el resumen está en abierto): los coliridianos «solo ofrecían a María una especie de veneración» como la que se daba a los santos.")

add(4, "The Qur'an Seminar Commentary (2016)", key="QS", specs=["P-QS"], lang="francés e inglés (páginas del libro, acceso abierto)",
 trnote="Traducción propia del francés y del inglés. ",
 title="Especialistas en el Corán: 5:116 no habla de «adoradores árabes de María», sino que es «una reducción al absurdo» o una «exageración» polémica",
 ref="M. Azaiez, G. S. Reynolds et al. (eds.), The Qur'an Seminar Commentary / Le Qur'an Seminar (De Gruyter, 2016, acceso abierto): G. Dye, p. 114; M. Pregill, p. 115; G. S. Reynolds, p. 261",
 ar_ref="QSC pp. 114, 115, 261", site="archive.org (PDF de acceso abierto, OAPEN)", url="https://archive.org/download/oapen-20.500.12657-45678/626408.pdf",
 es=["[Guillaume Dye:] V. 116: este versículo ha dado lugar a muchas especulaciones. [[k:Se han imaginado]] [[k:adoradores árabes de María que serían el blanco de este versículo]], o se ha visto en él una prueba de que el autor del Corán desconocía el cristianismo y hacía de María una de las personas de la Trinidad. Me parece más bien que hay que ver aquí [[k:un argumento polémico, una reducción al absurdo del discurso cristiano]], que puede funcionar de dos maneras (también se puede ver, claro, una polémica contra las prácticas de culto cristianas).",
     "[Michael Pregill:] La amenaza contra los que no crean después de recibir este signo (v. 115) es ciertamente ominosa, dada la alusión que sigue [[k:a la injusta divinización de Jesús y María por parte de los cristianos.]] [[k:Todo el pasaje parece hecho para exculpar a los profetas]] de los crímenes de sus seguidores (y subrayar estos), con Jesús como el ejemplo principal.",
     "[Gabriel Said Reynolds:] …En este sentido, los «dioses» (aliha) del v. 3 podrían no reflejar politeísmo, sino [[k:la tendencia del Corán a exagerar las opiniones de sus adversarios]] ([[k:podríamos comparar esta estrategia con 5:116, que sugeriría]] que los cristianos adoran a María; o con 9:31, que sugeriría que los judíos adoran a sus rabinos y los cristianos a sus monjes)."],
 prueba="Tres especialistas académicos en el Corán, en una obra de referencia. Ninguno recurre a los coliridianos. Dye rechaza la idea de unos «adoradores árabes de María». Para Dye es una «reducción al absurdo» del lenguaje cristiano («Madre de Dios»), y para Reynolds, una «exageración» deliberada de las ideas del adversario, como en 9:31.",
 ojo="Estas lecturas no dicen que el Corán «se equivocara»: dicen que 5:116 es polémica, no una descripción. Para el debate, eso basta: el versículo no prueba que existiera una trinidad con María. Pregill habla de «la divinización de Jesús y María por los cristianos», pero como lo que el Corán les reprocha.")

add(4, "R. Ramishvili y N. Gelovani (2026)", key="RG", specs=["P-RG"], lang="inglés (páginas del artículo, acceso abierto)",
 trnote="Traducción propia del inglés. ",
 title="Incluso un artículo que defiende que los coliridianos existieron admite: Juan Damasceno «no aporta nada nuevo» y «todas las fuentes dependen del Panarion»",
 ref="Rati Ramishvili y Nani Gelovani, «The Collyridians in Early Christian…», Herald of Oriental Studies 9/1 (2026), pp. 313 y 316",
 ar_ref="HOS 9/1 (2026), pp. 313, 316", site="hos.openjournals.ge (PDF de acceso abierto)", url="https://hos.openjournals.ge/index.php/hos/article/download/11624/11125/20448",
 es=["Las fuentes sobre la existencia de los coliridianos son bastante modestas. Obtenemos una información relativamente amplia y detallada de la monumental obra antiherética de san Epifanio, obispo del siglo IV: el Panarion. Juan Damasceno, autor de los primeros tratados contra el islam, [[k:repite los datos del autor anterior y no aporta nada nuevo]]. Después de Juan Damasceno (750 d. C.), [[k:las fuentes griegas callan, y el turno pasa a las fuentes árabes:]] a esta secta la menciona el patriarca diofisita de Alejandría, Eutiquio, y a partir de él el monofisita [[k:Ibn Kabar (1324 d. C.) la incluye en su lista de herejías]]. Estos dos autores llaman a los seguidores de la herejía «maryamiyyun» (Benko, 2004: 193).",
     "El principal problema para determinar la existencia o el credo exacto de los coliridianos es la ausencia total de documentos o de [[k:fuentes independientes producidas por la propia confesión]]. Además, no tenemos información sobre cuándo y sobre qué base surgió esta doctrina. Aunque tenemos relatos hasta el siglo VI que mencionan a los coliridianos, [[k:todos ellos dependen del Panarion]], escrito por Epifanio en la década de 370 (Carroll, 1986: 44)."],
 prueba="Es un artículo que defiende que 5:116 responde a los coliridianos, y aun así reconoce el problema: no hay ninguna fuente independiente. Juan Damasceno copia a Epifanio, y las únicas noticias posteriores son árabes: Eutiquio (#Bt#) e Ibn Kabar, que depende de él.",
 ojo="El artículo es reciente (2026) y de una revista menor. Lo citamos por lo que concede, no como autoridad. Que Eutiquio llame a la secta «maryamiyyun» no la conecta con los coliridianos de Epifanio: no menciona tortas, ni mujeres, ni Arabia.")
